TLM.f("Sancti/03-09",{"officium":"S. Franciscæ Viduæ Romanæ","rule":["vide C7a;","Gloria"],"fallback":"Commune/C7a","from":{"Introitus":"Commune/C7a","Lectio":"Commune/C7a","Graduale":"Commune/C7a","GradualeP":"Commune/C7a","Tractus":"Commune/C7a","Evangelium":"Commune/C7a","Offertorium":"Commune/C7a","Secreta":"Commune/C7a","Communio":"Commune/C7a","Postcommunio":"Commune/C7a"},"sections":{"Introitus":[{"k":"ref","la":"Ps 118:75; 118:120"},{"k":"text","la":"Cognóvi, Dómine, quia ǽquitas judícia tua, et in veritáte tua humiliásti me: confíge timóre tuo carnes meas, a mandátis tuis tímui. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 118:1"},{"k":"text","la":"Beáti immaculáti in via: qui ámbulant in lege Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Cognóvi, Dómine, quia ǽquitas judícia tua, et in veritáte tua humiliásti me: confíge timóre tuo carnes meas, a mandátis tuis tímui. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui beátam Francíscam fámulam tuam, inter cétera grátiæ tuæ dona, familiári Angeli consuetúdine decorásti: concéde, quǽsumus; ut, intercessiónis ejus auxílio, Angelórum consórtium cónsequi mereámur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"rubric","la":"Prov 31:10-31"},{"k":"text","la":"Mulíerem fortem quis invéniet? Procul et de últimis fínibus prétium ejus. Confídit in ea cor viri sui, et spóliis non indigébit. Reddet ei bonum, et non malum, ómnibus diébus vitæ suæ. Quæsívit lanam et linum, et operáta est consílio mánuum suárum. Facta est quasi navis institóris, de longe portans panem suum. Et de nocte surréxit, dedítque prædam domésticis suis, et cibária ancíllis suis. Considerávit agrum, et emit eum: de fructu mánuum suárum plantávit víneam. Accínxit fortitúdine lumbos suos, et roborávit bráchium suum. Gustávit, et vidit, quia bona est negotiátio ejus: non exstinguétur in nocte lucérna ejus. Manum suam misit ad fórtia, et dígiti ejus apprehendérunt fusum. Manum suam apéruit ínopi, et palmas suas exténdit ad páuperem. Non timébit dómui suæ a frigóribus nivis: omnes enim doméstici ejus vestíti sunt duplícibus. Stragulátam vestem fecit sibi: byssus et púrpura induméntum ejus. Nóbilis in portis vir ejus, quando séderit cum senatóribus terræ. Síndonem fecit et véndidit, et cíngulum trádidit Chananǽo. Fortitúdo et decor induméntum ejus, et ridébit in die novíssimo. Os suum apéruit sapiéntiæ, et lex cleméntiæ in lingua ejus. Considerávit sémitas domus suæ, et panem otiósa non comédit. Surrexérunt fílii ejus, et beatíssimam prædicavérunt: vir ejus, et laudávit eam, Multæ fíliæ congregavérunt divítias: tu supergréssa es univérsas. Fallax grátia, et vana est pulchritúdo: múlier timens Dóminum, ipsa laudábitur. Date ei de fructu mánuum suárum: et laudent eam in portis ópera ejus."}],"Graduale":[{"k":"ref","la":"Ps 44:3; 44:5"},{"k":"text","la":"Diffúsa est grátia in labiis tuis: proptérea benedíxit te Deus in ætérnum."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 44:3; 44:5"},{"k":"text","la":"Diffúsa est grátia in labiis tuis: proptérea benedíxit te Deus in ætérnum."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et de ducet te mirabíliter déxtera tua.","mark":"V"},{"k":"text","la":"Veni, Sponsa Christi, áccipe coronam, quam tibi Dóminus præparávit in ætérnum."},{"k":"ref","la":"Ps 44:8; 44:5"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, oleo lætítiæ præ consórtibus tuis."},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 13:44-52"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile est regnum cœlórum thesáuro abscóndito in agro: quem qui invénit homo, abscóndit, et præ gáudio illíus vadit, et vendit univérsa, quæ habet, et emit agrum illum. Íterum símile est regnum cœlórum hómini negotiatóri, quærénti bonas margarítas. Invénta autem una pretiósa margaríta, ábiit, et véndidit ómnia, quæ hábuit, et emit eam. Íterum símile est regnum cœlórum sagénæ missæ in mare et ex omni génere píscium congregánti. Quam, cum impléta esset, educéntes, et secus litus sedéntes, elegérunt bonos in vasa, malos autem foras misérunt. Sic erit in consummatióne sǽculi: exíbunt Angeli, et separábunt malos de médio justórum, et mittent eos in camínum ignis: ibi erit fletus et stridor déntium. Intellexístis hæc ómnia? Dicunt ei: Etiam. Ait illis: Ideo omnis scriba doctus in regno cœlórum símilis est hómini patrifamílias, qui profert de thesáuro suo nova et vétera."}],"Offertorium":[{"k":"ref","la":"Ps 44:3"},{"k":"text","la":"Diffúsa est grátia in lábiis tuis: proptérea benedíxit te Deus in ætérnum, et in sǽculum sǽculi."}],"Secreta":[{"k":"text","la":"Accépta tibi sit, Dómine, sacrátæ plebis oblátio pro tuórum honóre Sanctórum: quorum se méritis de tribulatióne percepísse cognóscit auxílium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 44:8"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis."}],"Postcommunio":[{"k":"text","la":"Satiásti, Dómine, famíliam tuam munéribus sacris: ejus, quǽsumus, semper interventióne nos réfove, cujus sollémnia celebrámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"22f06d2440d0fa00":{"t":"<i>Pomolimo se</i>.\nBože, koji si blaženu svoju službenicu Francisku, pored ostalih darova tvoje milosti, ukrasio društvom anđela, podaj, molimo, da s pomoću njenog zagovora zavrijedimo združiti se s anđelima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.\n[preveo M.B. po uredbi iz 1967. nisu u korizmi dozvoljeni spomeni; ovaj dan može biti izvan korizme pa je, čini se, greškom ispušten iz Radićevog prijevoda Misala.]"},"135c5bf58bce477d":{"t":"Pogledaj, Gospodine, na darove svoga naroda, i daj mu osjetiti da mu koristi za spasenje ova žrtvena svečanost koju obavlja s pobožnom odanošću na čast tvojih svetih.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"dfce8e9a1c23b4e0":{"t":"<i>Pomolimo se</i>.\nNasitio si, Gospodine, svoju obitelj svetim darovima, molimo da nas uvijek krijepiš na zagovor one čiju svečanost slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, pošto si nahranio svoju obitelj presvetim darovima, da nas uvijek krijepiš zagovorom one, koje blagdan slavimo, Po G. n.","knRef":"Kniewald 1942, str. 506–507 (snimka 254) (OCR)"}}});
